ALTER TABLE attendance_deduction_rules ADD COLUMN "durationThresholdMinutes" DOUBLE PRECISION, ADD COLUMN "overThresholdDeductionDays" DOUBLE PRECISION;
ALTER TABLE attendance_deduction_rules ADD CONSTRAINT attendance_timing_bands_valid CHECK (("durationThresholdMinutes" IS NULL AND "overThresholdDeductionDays" IS NULL) OR ("ruleKey" IN ('LATE','EARLY_CHECKOUT') AND "durationThresholdMinutes" IS NOT NULL AND "overThresholdDeductionDays" IS NOT NULL AND "durationThresholdMinutes">0 AND "durationThresholdMinutes"<=1440 AND "overThresholdDeductionDays">0 AND "overThresholdDeductionDays"<=1));
